//go:build arm64

package floats

// The NEON kernel of MulAddRows32 (mulrows32.go), generated by go-asmgen
// (mulrows32_arm64_gen.go) into mulrows32_arm64.s: blocks of 16, 4 and 1 columns, the
// block of dst held in registers across all the rows. NEON is the ARMv8-A baseline: no
// gate. The caller guarantees rows >= 1, len(dst) >= 1 and the lengths of a and b. No
// kernel keeps a pointer: go:noescape.
//
//go:noescape
func mulAddRows32NEON(dst, a []float32, lda int, b []float32, ldb int, rows int)

func mulAddRows32(dst, a []float32, lda int, b []float32, ldb int, rows int) {
	mulAddRows32NEON(dst, a, lda, b, ldb, rows)
}
